class _AliasLoader(importlib.abc.Loader):
    def __init__(self, target: str):
        self.target = target

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        target = importlib.import_module(self.target)
        protected = {"__name__", "__package__", "__loader__", "__spec__"}
        for key, value in target.__dict__.items():
            if key not in protected:
                module.__dict__[key] = value
        module.__dict__["__nkt_canonical_module__"] = self.target

class _AliasFinder(importlib.abc.MetaPathFinder):
    _nkt_backend_alias_finder = True
    def find_spec(self, fullname, path=None, target=None):
        canonical = ALIASES.get(fullname)
        if not canonical:
            return None
        return importlib.util.spec_from_loader(fullname, _AliasLoader(canonical), origin=f"nkt-alias:{canonical}")

def install():
    if not any(getattr(x, "_nkt_backend_alias_finder", False) for x in sys.meta_path):
        sys.meta_path.insert(0, _AliasFinder())

install()
